sys_script_include.script:
var Hoc_CotlUtils = Class.create();
Hoc_CotlUtils.prototype = {
    initialize: function() {},

    checkReadyForShipping: function(worksheet, filter, number) {
        var cotltask = new GlideAggregate('x_hccc_cotl_task');
        cotltask.addEncodedQuery(filter + worksheet);
        cotltask.addAggregate('COUNT');
        cotltask.query();

        if (cotltask.next()) {
            var count = cotltask.getAggregate('COUNT');
            return count > number ? "No" : "Yes";
        }

        return "Yes";
    },

    hardwareassetsstate: function(cotltask, table, state, substatus, assestfieldname, number) {
        var cotl = new GlideRecord('x_hccc_cotl_task');

        try {
            if (cotl.get(cotltask)) {
                // var howManyComputers = parseInt(cotl.worksheet.how_many_computers, 10);

                gs.info("Number of assets: " + number);

                for (var i = 1; i <= number; i++) {
                    var fieldname = assestfieldname + i;
                    var field = cotl.getValue(fieldname);

                    gs.info('Checking field: ' + fieldname + ' with sys_id = ' + field);
                    if (field && field.trim() != '') {
                        gs.info('Field has value and enters loop: ' + field);

                        var asset = new GlideRecord(table);


                        if (asset.get(field)) {
                            gs.info('Asset found and updating: ' + field);

                            // Mettre à jour les valeurs
                            asset.setValue('install_status', state);
                            asset.setValue('substatus', substatus);
                            asset.update();
                            gs.info('Asset updated for field ' + fieldname);
                        } else {
                            gs.info('Asset not found for field ' + fieldname + ' with sys_id: ' + field, 'error');
                        }
                    } else {
                        gs.info('Field ' + fieldname + ' is empty or invalid (sys_id).', 'error');
                    }
                }
            } else {
                gs.info('Cotl task not found with ID: ' + cotltask, 'error');
            }
        } catch (e) {
            gs.info('Error in hardwareassetsstate function: ' + e.message, 'error');
            gs.info('Stack trace: ' + e.stack, 'error');
        }
    },

    taskassociated: function(worksheet) {
        var cotltask = new GlideAggregate('x_hccc_cotl_task');
        cotltask.addEncodedQuery("worksheet=" + worksheet.sys_id);
        cotltask.addAggregate('COUNT');
        cotltask.query();
        var count = cotltask.next() ? cotltask.getAggregate('COUNT') : 0;
        var result = (count == 0) && worksheet.state == '2' && worksheet.request_type != '';
        return result;
    },

    checkcheckliststatut: function(uniqueid) {
        var result = true;
        var ci = new GlideRecord('checklist_item');
        ci.addQuery('checklist.document', uniqueid);
        ci.addQuery('complete', false);
        ci.query(); // 
        if (ci.next()) {
            gs.addErrorMessage('All checklist items must be completed before moving to the "Ready for Shipping" stage.');
            result = false;
        }
        return result;
    },

    cotlrecordcheck: function(worksheet,table) {
        if (!worksheet || !worksheet.sys_id) {
            return true;
        }
        var cotltask = new GlideAggregate(table);
        cotltask.addQuery('parent', worksheet.sys_id);
        cotltask.addAggregate('COUNT');
        cotltask.query();
        if (cotltask.next()) {
            var count = parseInt(cotltask.getAggregate('COUNT'), 10) || 0;
            return count === 0;
        }
        return true;
    },

    type: 'Hoc_CotlUtils'
};
